    $insertQStmt = $db->prepare("
        INSERT INTO questions (
            subtopic_id, question_text, code_snippet, language,
            option_a, option_b, option_c, option_d, correct_option,
            explanation, difficulty, est_time_seconds,
            is_published, verification_level, company_name, source_tag
        ) VALUES (
            ?, ?, ?, ?,
            ?, ?, ?, ?, ?,
            ?, ?, ?,
            1, 'verified', ?, ?
        )
    ");

    $insertedCount = 0;
    $alreadyCount = 0;

    foreach ($questionsData as $q) {
        $compName = $q['company_name'];
        $checkQStmt->execute([$q['question_text'], $compName]);
        if ($checkQStmt->fetchColumn()) {
            $alreadyCount++;
            continue;
        }

        $insertQStmt->execute([
            $q['subtopic_id'],
            $q['question_text'],
            $q['code_snippet'] ?? null,
            $q['language'] ?? null,
            $q['option_a'],
            $q['option_b'],
            $q['option_c'],
            $q['option_d'],
            $q['correct_option'],
            $q['explanation'],
            $q['difficulty'],
            $q['est_time_seconds'],
            $compName,
            $q['source_tag']
        ]);
        $insertedCount++;
    }

    echo "  [+] Ingestion complete. Newly inserted PYQs: $insertedCount (Already existed: $alreadyCount)\n";

    // Ensure all questions are published and verified
    $db->exec("UPDATE questions SET is_published = 1, verification_level = 'verified' WHERE is_published = 0 OR verification_level != 'verified'");

